a("<th>Verband</th><th>n</th><th style='text-transform:none'>rho</th><th>95%-interval</th><th>p</th><th>Lees als</th>","<th>Relationship</th><th>n</th><th style='text-transform:none'>rho</th><th>95% interval</th><th>p</th><th>Read as</th>")
a("f\"{lo:.2f} tot {hi:.2f}\"","f\"{lo:.2f} to {hi:.2f}\"")
a("<h3>Methode</h3><p class='mini'>Rangcorrelatie (Spearman), betrouwbaarheidsinterval via 5.000 bootstrap-trekkingen. Landen: 27 EU-lidstaten, bedrijven met 10+ medewerkers, 2025 (Eurostat). Sectoren: 12 CBS-sectoren, 2+ medewerkers, 2023–2025. Privégebruik: 15 landen met Microsoft-data.","<h3>Method</h3><p class='mini'>Rank correlation (Spearman), confidence interval via 5,000 bootstrap draws. Countries: 27 EU member states, companies with 10+ employees, 2025 (Eurostat). Sectors: 12 CBS sectors, 2+ employees, 2023–2025. Private use: 15 countries with Microsoft data.")
a("<h3>Wat dit niet is</h3><p class='mini'>Geen oorzaak-en-gevolg. Een kleine n maakt intervallen breed. &ldquo;Niet significant&rdquo; betekent niet &ldquo;geen verband&rdquo;, maar: niet aantoonbaar met deze data. Eurostat en CBS meten andere groepen, dus we hebben ze niet gemengd.","<h3>What this is not</h3><p class='mini'>Not cause and effect. A small n makes intervals wide. &ldquo;Not significant&rdquo; does not mean &ldquo;no relationship&rdquo;, but: not demonstrable with this data. Eurostat and CBS measure different groups, so we did not mix them.")
a("<h3 style='margin-top:6mm'>Zo zeker zijn we: correlatie met 95%-interval</h3>","<h3 style='margin-top:6mm'>How sure we are: correlation with 95% interval</h3>")
a("Goud: interval ligt los van nul. Grijs: aantoonbaar verband ontbreekt.","Gold: interval is clear of zero. Grey: no demonstrable relationship.")
a("Wij beweren niet dat dit nog nooit iemand zag. Wij laten zien <b>hoe zeker</b> we zijn. Dat is het verschil.","We do not claim nobody has ever seen this. We show <b>how sure</b> we are. That is the difference.")
a("<span class='lab'>Eigen analyse</span>Alle berekeningen en ruwe cijfers staan in de database bij het magazine (tabellen country_ai, sector_ai, analysis_results).<br>Bron: Eurostat KS-01-26-009, CBS (sectoren), eigen berekening Bedrijfsgeheugen, november 2026.","<span class='lab'>Own analysis</span>All calculations and raw figures are in the database that comes with the magazine (tables country_ai, sector_ai, analysis_results).<br>Source: Eurostat KS-01-26-009, CBS (sectors), own calculation Bedrijfsgeheugen, November 2026.")
for nl,en in [("('Totaal ~ klein','totaal vs small')","('Total ~ small','totaal vs small')"),("('Totaal ~ groot','totaal vs large')","('Total ~ large','totaal vs large')"),("('Groot, gegeven klein','partieel","('Large, given small','partieel"),("('Klein/groot-verhouding','totaal","('Small/large ratio','totaal"),("('Aandeel marketing',","('Share marketing',"),("('Aandeel administratie',","('Share administration',"),("('Groei pp ~ niveau',","('Growth pp ~ level',"),("('Relatieve groei ~ niveau',","('Relative growth ~ level',"),("('Privégebruik gen-AI','bedrijfsadoptie","('Private use gen-AI','bedrijfsadoptie"),("('Sector: groei ~ niveau',","('Sector: growth ~ level',")]: a(nl,en)
